package app

import (
	"context"
	"fmt"
	"log/slog"
	"path/filepath"
	"runtime"

	core "github.com/cambrian-sh/core"
	"github.com/cambrian-sh/core/internal/config"
	"github.com/cambrian-sh/core/internal/pyenv"
	"github.com/cambrian-sh/core/internal/sandbox"
)

// baseLockPath is the release's hashed base lock inside the embedded agents
// tree (ADR-0157 D7.4.2; generated by scripts/gen_agent_requirements.py).
const baseLockPath = "agents/base.lock"

// newPythonEnvBuilder is the one env builder setup step 4, the python-env CLI
// and the boot check all use (ADR-0157 D7.11.1): the embedded pin table, this
// host's platform, the embedded base lock, and execution.agents.python's
// sources. baseDir anchors the env root; configDir anchors relative
// wheelhouse entries.
func newPythonEnvBuilder(pc config.AgentPythonConfig, baseDir, configDir string) (*pyenv.Builder, error) {
	pins, err := pyenv.Pins()
	if err != nil {
		return nil, err
	}
	platform, err := pyenv.HostPlatform()
	if err != nil {
		return nil, err
	}
	lock, err := core.AgentsFS.ReadFile(baseLockPath)
	if err != nil {
		return nil, fmt.Errorf("embedded base lock %s: %w", baseLockPath, err)
	}
	// ADR-0157 D7.7.5: on Windows a new generation gets the AppContainer
	// agents' inheritable read ACE while it is still empty, so the launch path
	// never walks its ~1 GiB tree. The Unix runners bind paths and need none.
	var prepare func(string) error
	if runtime.GOOS == "windows" {
		prepare = sandbox.GrantAgentRuntimeRead
	}
	return &pyenv.Builder{
		PrepareGeneration: prepare,
		Root:              pc.ResolvedRoot(absOr(baseDir)),
		Pins:              pins,
		Platform:          platform,
		Lock:              lock,
		Sources: pyenv.Sources{
			PythonMirror:    pc.PythonMirrorURL,
			InstallerMirror: pc.InstallerMirrorURL,
			IndexURL:        pc.IndexURL,
			Wheelhouse:      pc.ResolvedWheelhouse(configDir),
			Offline:         pc.Offline,
		},
	}, nil
}

// startPythonEnv runs the boot check of the kernel-managed Python env and, with
// build_on_boot, starts its background build (ADR-0157 D7.11.2). The kernel
// boots either way; only Python agent spawns wait on the returned gate. A
// builder that cannot even be constructed (an unpinned platform, a missing
// embedded lock) still yields a gate — one that refuses with the reason.
func startPythonEnv(ctx context.Context, cfg *config.Config, baseDir string) pythonEnvGate {
	pc := cfg.Execution.Agents.Python
	b, err := newPythonEnvBuilder(pc, baseDir, filepath.Join(baseDir, "configs"))
	if err != nil {
		slog.Error("ADR-0157 D7: sandbox Python env unavailable on this host; Python agents will be refused", "err", err)
		return refusedPythonEnv{err: err}
	}
	env := pyenv.NewEnv(b, pc.BuildOnBoot)
	env.Start(ctx)
	return env
}

// pythonEnvGate is what the kernel keeps of the env: the interpreter every
// Python agent and Python system tool launches on (agentmgr.PythonEnv), plus
// Stop for shutdown.
type pythonEnvGate interface {
	Interpreter() (pyenv.Interpreter, error)
	Stop()
}

type refusedPythonEnv struct{ err error }

func (r refusedPythonEnv) Interpreter() (pyenv.Interpreter, error) {
	return pyenv.Interpreter{}, fmt.Errorf("sandbox Python env unavailable: %w", r.err)
}
func (refusedPythonEnv) Stop() {}

// pythonInterpreterPath adapts the env to the Python system tools' resolver
// (toolproc.ProcessHandler.Interpreter): the same managed interpreter as the
// agents, read per call (ADR-0157 D7.14, one interpreter).
func pythonInterpreterPath(env pythonEnvGate) func() (string, error) {
	return func() (string, error) {
		pi, err := env.Interpreter()
		return pi.Path, err
	}
}
